                .externalId(
                    e.getDetails()
                        .getFirst()
                        .getOrDefault("externalId", transaction.getExternalId()))
                .build();

        transactionService.partialUpdate(partialUpdate);
        chargeStateMetadata.setPspStatus(PspStatus.CANCELLED);
        chargeStateMetadata.setPspDeclineCode(getDeclineCode(e));
        String declineCode = getDeclineCode(e);
        try {
          declineCodeConfig =
              Optional.ofNullable(declineCode)
                  .map(code -> declineCodeService.getDeclineCodeConfig(transaction.getPsp(), code))
                  .orElseThrow(
                      () ->
                          new TransactionCreateException(
                              LogUtils.getCorrelationId(),
                              "Decline code is null for RecurringChargeId: %s"
                                  .formatted(recurringCharge.getRecurringChargeId()),
                              500));
        } catch (PaymentServiceException ex) {
          logger.error(
              "Decline code config not found for decline code: {} on RecurringChargeId: {}",
              declineCode,
              recurringCharge.getRecurringChargeId(),
              ex);
          throw new TransactionCreateException(
              LogUtils.getCorrelationId(),
              "Failed to create transaction for RecurringChargeId: %s, declineCode: %s, configuration missing for decline code"
                  .formatted(recurringCharge.getRecurringChargeId(), declineCode),
              500,
              e);
        }
      } else {
        HttpStatus statusCode =
            e.getStatusCode() == BAD_REQUEST.value() ? BAD_REQUEST : PAYMENT_REQUIRED;
        String reason = statusCode == BAD_REQUEST ? ", Reason: " + e.getMessage() : "";
        throw new TransactionCreateException(
            LogUtils.getCorrelationId(),
            "Failed to create transaction for RecurringChargeId: %s%s"
                .formatted(recurringCharge.getRecurringChargeId(), reason),
            statusCode.value(),
            e);
      }
